@@ -1,3 +1,37 @@
+const UNIT_MS = {
+  d: 86_400_000,
+  h: 3_600_000,
+  m: 60_000,
+  s: 1_000,
+  ms: 1,
+};
+
+const COMPONENT_RE = /^(\d+)(ms|d|h|m|s)\s*/;
+
 export function parseDuration(value) {
-  return Number(value);
+  if (typeof value !== "string" || value.trim() === "") {
+    throw new Error("Invalid duration: input must be a non-empty string");
+  }
+
+  let remaining = value.trim();
+  const seen = new Set();
+  let totalMs = 0;
+
+  while (remaining.length > 0) {
+    const match = COMPONENT_RE.exec(remaining);
+    if (!match) {
+      throw new Error(`Invalid duration: unable to parse "${remaining}"`);
+    }
+
+    const [full, amountStr, unit] = match;
+    if (seen.has(unit)) {
+      throw new Error(`Invalid duration: duplicate unit "${unit}"`);
+    }
+    seen.add(unit);
+
+    totalMs += Number(amountStr) * UNIT_MS[unit];
+    remaining = remaining.slice(full.length);
+  }
+
+  return totalMs;
 }
